def countEqualXorTriplets(arr):
    count = {}
    index_sum = {}
    prefix = 0
    ans = 0
    for m in range(len(arr) + 1):
        if m > 0:
            prefix ^= arr[m - 1]
        c = count.get(prefix, 0)
        ans += c * (m - 1) - index_sum.get(prefix, 0)
        count[prefix] = c + 1
        index_sum[prefix] = index_sum.get(prefix, 0) + m
    return ans % 1000000007
